CREATE VIEW current_threads AS SELECT t.*,(SELECT title FROM thread_title_observations o WHERE o.thread_id=t.thread_id ORDER BY observation_id DESC LIMIT 1) AS title,(SELECT cwd FROM thread_cwd_observations o WHERE o.thread_id=t.thread_id ORDER BY observation_id DESC LIMIT 1) AS cwd,(SELECT archived FROM thread_archive_observations o WHERE o.thread_id=t.thread_id ORDER BY observation_id DESC LIMIT 1) AS archived FROM threads t;
